import { el } from '../utils.js';

/* ============================================================
   Fondo Apapacho — la marca de la causa
   ------------------------------------------------------------
   El corazón es el logo que nos pasó el club, recortado del
   original y guardado AQUÍ DENTRO como webp en base64 (16 KB).
   Va embebido a propósito, no como archivo suelto: así no hay
   una petición más que pueda fallar ni un archivo que se pueda
   quedar sin subir, y la noche con causa nunca sale a medias.

   El nombre NO viene de la imagen: se escribe con la tipografía
   de la app, "Fondo" en blanco y "Apapacho" en rosa, que es como
   lo pidió el club para que combine con el resto de la app.

   Este módulo se carga solo cuando hay una noche con causa, así
   que esos 16 KB no le cuestan nada a quien nunca la ve.
   ============================================================ */

export const CORAZON_APAPACHO = 'data:image/webp;base64,';

/* El corazón con el nombre debajo. `alto` es el alto del corazón en píxeles. */
export function logoApapacho({ alto = 64, conNombre = true, centrado = true } = {}) {
  const caja = el('div', {
    class: 'marca-causa' + (centrado ? ' marca-causa-centro' : ''),
  });

  const img = el('img', {
    class: 'corazon-apapacho',
    src: CORAZON_APAPACHO,
    alt: 'Fondo Apapacho',
    width: String(Math.round(alto * 360 / 307)),
    height: String(alto),
    loading: 'eager',
    decoding: 'async',
    // Reservar el espacio evita el salto al cargar; sin esto la
    // tarjeta brinca cuando entra la imagen.
    style: `height:${alto}px;width:auto;aspect-ratio:360/307;`,
  });
  caja.appendChild(img);

  if (conNombre) {
    caja.appendChild(el('div', { class: 'nombre-causa' }, [
      el('span', { class: 'nc-1' }, 'Fondo'),
      el('span', { class: 'nc-2' }, 'Apapacho'),
    ]));
  }
  return caja;
}

/* Aviso con la explicación de la causa. Sale igual en la tarjeta de
   Convocatorias y en la página de la noche: una sola redacción, que
   además viene de la base (catalogo_causas), no escrita aquí. */
export function avisoCausa(info) {
  return el('div', { class: 'aviso-causa mt-3' }, [
    el('p', { style: 'font-size:13.5px;line-height:1.5;' }, info.que_es || ''),
    el('p', { class: 'text-tiny mt-2', style: 'color:var(--causa);font-weight:700;' },
      info.destino || ''),
  ]);
}

/* "Llevamos recaudado $X". Solo se pinta si ya hay algo de verdad en la
   caja: presumir $0 el primer día desanima en vez de animar. */
export function panelRecaudado(r) {
  if (!r) return null;
  const total = Number(r.total_mxn || 0);
  const prox = Number(r.proxima_mxn || 0);
  if (total <= 0 && prox <= 0) return null;

  const caja = el('div', { class: 'recaudado mt-3' });
  if (total > 0) {
    caja.appendChild(el('div', { class: 'monto' }, '$' + total.toLocaleString('es-MX')));
    caja.appendChild(el('div', { class: 'pie-monto' },
      `donados en ${r.noches} ${r.noches === 1 ? 'mañana' : 'mañanas'}, `
      + `entre ${r.jugadores} ${r.jugadores === 1 ? 'jugador' : 'jugadores'}`));
  }
  if (prox > 0) {
    caja.appendChild(el('p', { class: 'text-tiny mt-2', style: 'color:var(--text-tertiary);' },
      total > 0
        ? `Y esta semana ya van $${prox.toLocaleString('es-MX')} más apuntados.`
        : `Esta semana ya van $${prox.toLocaleString('es-MX')} apuntados. Cada lugar suma $${Number(r.precio_mxn).toLocaleString('es-MX')}.`));
  }
  return caja;
}
